TYPE.TEST:


SetFunctionName("Vector3Plus&      operator = (Vector3Plus::InParam v)");
Vector3Plus vRef( 1.0f, 2.1f, 3.2f, 4.3f );
Vector3Plus v;
v= vRef;
Validate((float)v.X() == 1.0f && (float)v.Y() == 2.1f && (float)v.Z() == 3.2f && (float)v.UserData() == 4.3f);



SetFunctionName("Vector3Plus(const Vector3Plus&)");
Vector3Plus vRef( 1.0f, 2.1f, 3.2f, 4.3f );
Vector3Plus v(vRef);
Validate((float)v.X() == 1.0f && (float)v.Y() == 2.1f && (float)v.Z() == 3.2f && (float)v.UserData() == 4.3f);



SetFunctionName("Vector3Plus(const Vector3&, userData)");
Vector3Plus v(Vector3(1.0f, 2.1f, 3.2f), float_test_type(4.3f));
Validate((float)v.X() == 1.0f && (float)v.Y() == 2.1f && (float)v.Z() == 3.2f && (float)v.UserData() == 4.3f);



#ifdef HOST_TESTING

            SetFunctionName("Vector3Plus(const fpu::Vector3PlusTemplate<FloatClassRHS> &_v)");
            ::rw::math::fpu::Vector3PlusTemplate<double> doubleUnalignedVector;
            ::rw::math::fpu::Vector3PlusTemplate<float> floatUnalignedVector;
            ::rw::math::fpu::Vector3PlusTemplate<double> doubleAlignedVector;
            ::rw::math::fpu::Vector3PlusTemplate<float> floatAlignedVector;

            doubleUnalignedVector.Set(
                0, 1, 2, 4
                );
            floatUnalignedVector.Set(
                0, 1, 2, 4
                );
            doubleAlignedVector.Set(
                0, 1, 2, 4
                );
            floatAlignedVector.Set(
                0, 1, 2, 4
                );

            Vector3Plus ref;
            ref.Set(
                0, 1, 2, 4
                );

            Vector3Plus test_doubleUnalignedVector(doubleUnalignedVector);
            Vector3Plus test_floatUnalignedVector(floatUnalignedVector);
            Vector3Plus test_doubleAlignedVector(doubleAlignedVector);
            Vector3Plus test_floatAlignedVector(floatAlignedVector);

            Validate(
                ((float)test_doubleUnalignedVector.X() == (float)ref.X() && (float)test_doubleUnalignedVector.Y() == (float)ref.Y() && (float)test_doubleUnalignedVector.Z() == (float)ref.Z() && (float)test_doubleUnalignedVector.UserData() == (float)ref.UserData()) &&
                ((float)test_floatUnalignedVector.X() == (float)ref.X() && (float)test_floatUnalignedVector.Y() == (float)ref.Y() && (float)test_floatUnalignedVector.Z() == (float)ref.Z() && (float)test_floatUnalignedVector.UserData() == (float)ref.UserData()) &&
                ((float)test_doubleAlignedVector.X() == (float)ref.X() && (float)test_doubleAlignedVector.Y() == (float)ref.Y() && (float)test_doubleAlignedVector.Z() == (float)ref.Z() && (float)test_doubleAlignedVector.UserData() == (float)ref.UserData()) &&
                ((float)test_floatAlignedVector.X() == (float)ref.X() && (float)test_floatAlignedVector.Y() == (float)ref.Y() && (float)test_floatAlignedVector.Z() == (float)ref.Z() && (float)test_floatAlignedVector.UserData() == (float)ref.UserData())
                );

#endif



SetFunctionName("Vector3Plus(VecFloat, VecFloat, VecFloat , VecFloat)");
Vector3Plus v(float_test_type(1.2f), float_test_type(2.3f), float_test_type(3.5f), float_test_type(4.5f));
Validate((float)v.X() == 1.2f && (float)v.Y() == 2.3f && (float)v.Z() == 3.5f && (float)v.UserData() == 4.5f);



#ifdef HOST_TESTING

            MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.0f, 4.0f);

            SetFunctionName("Vector3Plus(VecFloatRef, VecFloatRef, VecFloatRef, VecFloatRef)");
            Vector3Plus v = Vector3Plus(VecFloatRefX(vi), VecFloatRefY(vi), VecFloatRefZ(vi), VecFloatRefW(vi));
            Validate((float)v.X() == 1.0f && (float)v.Y() == 2.0f && (float)v.Z() == 3.0f && (float)v.UserData() == 4.0f);

#endif



#ifdef HOST_TESTING

            MakeVectorIntrinsic(vi, 1.01f, 2.01f, 3.01f, 4.4f);

            SetFunctionName("Vector3Plus(VecFloatRefIndex, VecFloatRefIndex, VecFloatRefIndex, VecFloatRefIndex)");
            Vector3Plus v(VecFloatRefIndex(vi,0), VecFloatRefIndex(vi,1), VecFloatRefIndex(vi,2), VecFloatRefIndex(vi,3));
            Validate((float)v.X() == 1.01f && (float)v.Y() == 2.01f && (float)v.Z() == 3.01f&& (float)v.UserData() == 4.4f);

#endif



#ifdef HOST_TESTING

            MakeVectorIntrinsic(vi, 1.1f, 2.1f, 3.1f, 4.1f);

            SetFunctionName("Vector3Plus(Vector4Intrinsic)");
            Vector3Plus v(vi);
            Validate((float)v.X() == 1.1f && (float)v.Y() == 2.1f && (float)v.Z() == 3.1f && (float)v.UserData() == 4.1f);

#endif



            SetFunctionName("Vector3Plus(const FloatClass _xyzplus[4])");

#ifdef HOST_TESTING
            {
                float floatData[] = {1.23f, 4.56f, 7.89f, 1.0f};
                AlignedFloatBuffer floatBuffer(floatData, sizeof(floatData));
                Vector3Plus vB(floatBuffer.GetFloatData());
                Validate((float)vB.X() == 1.23f && (float)vB.Y() == 4.56f && (float)vB.Z() == 7.89f && (float)vB.UserData() == 1.0f);
            }
#endif
            {
                float_basic_type fArray[4]={1.23f, 4.56f, 7.89f, 1.0f};
                Vector3Plus vB(fArray);
                Validate((float)vB.X() == 1.23f && (float)vB.Y() == 4.56f && (float)vB.Z() == 7.89f && (float)vB.UserData() == 1.0f);
            }



SetFunctionName("Vector3Plus(float, float)");
Vector3Plus v(1.2f, 2.3f);
Validate((float)v.X() == 1.2f && (float)v.Y() == 1.2f && (float)v.Z() == 1.2f && (float)v.UserData() == 2.3f);



Vector3Plus v3;

SetFunctionName("Set(float, float, float)");
v3.Set(1.1f, 2.2f, 3.4f, 4.5);
