SetFunctionName("Set(Vector3, VecFloat)");
Vector3 v3(1.0f, 2.1f, 3.2f);
Vector3Plus v;
v.Set(v3, float_test_type(4.3f));
Validate((float_basic_type)v.X() == 1.0f && (float_basic_type)v.Y() == 2.1f && (float_basic_type)v.Z() == 3.2f && (float_basic_type)v.UserData() == 4.3f);



SetFunctionName("SetComponent(int i, float value)");
Vector3Plus v( 1.0f, 2.0f, 3.0f, 4.0f );
v.SetComponent( 1, 10.0f );
Validate((float)v.X() == 1.0f && (float)v.Y() == 10.0f && (float)v.Z() == 3.0f&& (float)v.UserData() == 4.0f);



#ifdef HOST_TESTING

            SetFunctionName("SetComponent(int i, VecFloat value)");
            Vector3Plus v( 1.0f, 2.0f, 3.0f, 4.0f );
            v.SetComponent( 1, VecFloat(12.0));
            Validate((float)v.X() == 1.0f && (float)v.Y() == 12.0f && (float)v.Z() == 3.0f && (float)v.UserData() == 4.0f);

#endif



#ifdef HOST_TESTING

            SetFunctionName("SetComponent(int i, VecFloatRefIndex value)");
