            v.SetComponent( 2, VecFloatRefIndex(vi,3) );
            Validate((float)v.X() == 1.0f && (float)v.Y() == 2.0f && (float)v.Z() == 4.1f && (float)v.UserData() == 4.0f);

#endif



#ifdef HOST_TESTING

            SetFunctionName("SetComponent(int i, VecFloatRef<INDEX> value)");
