            v.SetComponent( 2, VecFloatRefZ(vi) );
            Validate((float)v.X() == 1.0f && (float)v.Y() == 2.0f && (float)v.Z() == 3.1f && (float)v.UserData() == 4.0f);

#endif



#ifdef HOST_TESTING

            SetFunctionName("VecFloatRefIndex Vector3Plus::GetComponent(int i)");
            Vector3Plus v( 1.0f, 2.0f, 3.0f, 4.0f );
            Validate(v.GetComponent(0) == VecFloat(1.0f) && v.GetComponent(1) == VecFloat(2.0f) && v.GetComponent(2) == VecFloat(3.0f) && v.GetComponent(3) == VecFloat(4.0f));

#endif



