v3p.SetVector3(v3);

SetFunctionName("SetVector3(Vector3)");
Validate((float_basic_type)v3p.X() == -1.1f && (float_basic_type)v3p.Y() == -2.2f && (float_basic_type)v3p.Z() == -3.3f);



